+
+    public static final int DEFAULT_PAGE = 0;
+    public static final int DEFAULT_SIZE = 100;
+
+    public int pageOrDefault() {
+        return page == null ? DEFAULT_PAGE : page;
+    }
+
+    public int sizeOrDefault() {
+        return size == null ? DEFAULT_SIZE : size;
+    }
